					SET @v_dSql += '								ON A.PARENT_ITEM_ID=B.CHILD_ITEM_ID                                                                                                     ' + char(10)
					SET @v_dSql += '								AND A.COMPANY_ID=B.COMPANY_ID                                                                                                           ' + char(10)
					SET @v_dSql += '									AND A.DIVISION_ID=B.DIVISION_ID                                                                                                     ' + char(10)
					SET @v_dSql += '									AND A.SITE_ID=B.SITE_ID                                                                                                             ' + char(10)
					--SET @v_dSql += '								INNER HASH JOIN SCM_ITEM_M PD1(NOLOCK)                                                                                                  ' + char(10)
					SET @v_dSql += '														INNER HASH JOIN #SCM_ITEM_M_TEMP PD1(NOLOCK)                                                                          ' + char(10)
					SET @v_dSql += '									ON A.COMPANY_ID=PD1.COMPANY_ID                                                                                                      ' + char(10)
					SET @v_dSql += '									AND A.DIVISION_ID=PD1.DIVISION_ID                                                                                                   ' + char(10)
					SET @v_dSql += '									AND A.SITE_ID=PD1.SITE_ID                                                                                                           ' + char(10)
					SET @v_dSql += '									AND A.PARENT_ITEM_ID=PD1.ITEM_ID                                                                                                    ' + char(10)
					--SET @v_dSql += '									AND PD1.ACTIVE_FLAG=''Y''                                                                                                           ' + char(10)
					--SET @v_dSql += '									--AND PD1.ITEM_TYPE=''P''                                                                                                           ' + char(10)
					SET @v_dSql += '								INNER HASH JOIN #SCM_ITEM_CLASS_M_TEMP PDC1(NOLOCK)                                                                                           ' + char(10)
					SET @v_dSql += '									ON PD1.ITEM_CLASS=PDC1.CLASS_ID                                                                                                     ' + char(10)
					--SET @v_dSql += '									AND PDC1.USE_FLAG=''Y''                                                                                                             ' + char(10)
					--SET @v_dSql += '								INNER HASH JOIN SCM_ITEM_M PD2(NOLOCK)                                                                                                  ' + char(10)
					SET @v_dSql += '								INNER HASH JOIN #SCM_ITEM_M_TEMP PD2(NOLOCK)                                                                                            ' + char(10)
					SET @v_dSql += '									ON A.COMPANY_ID=PD2.COMPANY_ID                                                                                                      ' + char(10)
					SET @v_dSql += '									AND A.DIVISION_ID=PD2.DIVISION_ID                                                                                                   ' + char(10)
					SET @v_dSql += '									AND A.SITE_ID=PD2.SITE_ID                                                                                                           ' + char(10)
					SET @v_dSql += '									AND A.CHILD_ITEM_ID=PD2.ITEM_ID                                                                                                     ' + char(10)
					--SET @v_dSql += '									AND PD2.ACTIVE_FLAG=''Y''                                                                                                           ' + char(10)
					--SET @v_dSql += '									--AND PD2.ITEM_TYPE <> ''R''                                                                                                        ' + char(10)
					SET @v_dSql += '								INNER HASH JOIN #SCM_ITEM_CLASS_M_TEMP PDC2(NOLOCK)                                                                                           ' + char(10)
					SET @v_dSql += '									ON PD2.ITEM_CLASS=PDC2.CLASS_ID                                                                                                     ' + char(10)
					--SET @v_dSql += '									AND PDC2.USE_FLAG=''Y''                                                                                                             ' + char(10)
					--SET @v_dSql += '						WHERE A.EFF_START_DATE <= DBO.SYSDATE1()                                                                                                        ' + char(10)
					--SET @v_dSql += '						AND A.EFF_END_DATE >= DBO.SYSDATE1()                                                                                                            ' + char(10)
					SET @v_dSql += '		WHERE 1 = 1			)                                                                                                                                                   ' + char(10)
					SET @v_dSql += '	,CTE_NODE AS	(                                                                                                                                                   ' + char(10)
					SET @v_dSql += '						SELECT                                                                                                                                          ' + char(10)
					SET @v_dSql += '								COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,PARENT_ITEM_ID,CHILD_ITEM_ID,KEY_DATE,EFF_START_DATE,EFF_END_DATE                               ' + char(10)
					SET @v_dSql += '								,PARENT_QTY,PARENT_UOM,CHILD_QTY,CHILD_UOM,PARENT_ITEM_TYPE,PARENT_ITEM_CLASS,PARENT_LEVEL_2_CODE,PARENT_LEVEL_3_NAME                   ' + char(10)
					SET @v_dSql += '								,CHILD_ITEM_TYPE,CHILD_ITEM_CLASS,CHILD_LEVEL_2_CODE,CHILD_LEVEL_3_NAME,ROOT_ITEM,ALT_ID,ALT_PRIORITY,NLEVEL,NPATH                      ' + char(10)
					SET @v_dSql += '								,PARENT_NICK_NAME,CHILD_NICK_NAME                                                                                                       ' + char(10)
					SET @v_dSql += '						FROM ROOT                                                                                                                                       ' + char(10)
					SET @v_dSql += '						UNION ALL                                                                                                                                       ' + char(10)
					SET @v_dSql += '						SELECT * FROM LVL1                                                                                                                              ' + char(10)
					SET @v_dSql += '						UNION ALL                                                                                                                                       ' + char(10)
					SET @v_dSql += '						SELECT * FROM LVL2                                                                                                                              ' + char(10)
					SET @v_dSql += '						UNION ALL                                                                                                                                       ' + char(10)
					SET @v_dSql += '						SELECT * FROM LVL3                                                                                                                              ' + char(10)
					SET @v_dSql += '						UNION ALL                                                                                                                                       ' + char(10)
					SET @v_dSql += '						SELECT * FROM LVL4                                                                                                                              ' + char(10)
					SET @v_dSql += '						UNION ALL                                                                                                                                       ' + char(10)
					SET @v_dSql += '						SELECT * FROM LVL5                                                                                                                              ' + char(10)
					SET @v_dSql += '						UNION ALL                                                                                                                                       ' + char(10)
					SET @v_dSql += '						SELECT * FROM LVL6                                                                                                                              ' + char(10)
					SET @v_dSql += '						UNION ALL                                                                                                                                       ' + char(10)
					SET @v_dSql += '						SELECT * FROM LVL7                                                                                                                              ' + char(10)
					SET @v_dSql += '						UNION ALL                                                                                                                                       ' + char(10)
					SET @v_dSql += '						SELECT * FROM LVL8                                                                                                                              ' + char(10)
					SET @v_dSql += '					)                                                                                                                                                   ' + char(10)
					SET @v_dSql += '	, BOM_NODE	(                                                                                                                                                       ' + char(10)
					SET @v_dSql += '					COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,PARENT_ITEM_ID,CHILD_ITEM_ID,KEY_DATE,EFF_START_DATE,EFF_END_DATE,PARENT_QTY                                ' + char(10)
					SET @v_dSql += '					,PARENT_UOM,CHILD_QTY,CHILD_UOM,PARENT_ITEM_TYPE,PARENT_ITEM_CLASS,PARENT_LEVEL_2_CODE,PARENT_LEVEL_3_NAME                                          ' + char(10)
					SET @v_dSql += '					,CHILD_ITEM_TYPE,CHILD_ITEM_CLASS,CHILD_LEVEL_2_CODE,CHILD_LEVEL_3_NAME                                                                             ' + char(10)
					SET @v_dSql += '					,NLEVEL,NPATH,ROOT                                                                                                                                  ' + char(10)
					SET @v_dSql += '					,PARENT_NICK_NAME,CHILD_NICK_NAME                                                                                                                   ' + char(10)
					SET @v_dSql += '				)                                                                                                                                                       ' + char(10)
					SET @v_dSql += '			AS	(                                                                                                                                                       ' + char(10)
					SET @v_dSql += '					SELECT	COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,PARENT_ITEM_ID,CHILD_ITEM_ID,KEY_DATE,EFF_START_DATE,EFF_END_DATE                                   ' + char(10)
					SET @v_dSql += '							,PARENT_QTY,PARENT_UOM,CHILD_QTY,CHILD_UOM,PARENT_ITEM_TYPE,PARENT_ITEM_CLASS,PARENT_LEVEL_2_CODE,PARENT_LEVEL_3_NAME                       ' + char(10)
					SET @v_dSql += '							,CHILD_ITEM_TYPE,CHILD_ITEM_CLASS,CHILD_LEVEL_2_CODE,CHILD_LEVEL_3_NAME,NLEVEL                                                              ' + char(10)
					SET @v_dSql += '							,NPATH,ROOT                                                                                                                                 ' + char(10)
					SET @v_dSql += '							,PARENT_NICK_NAME,CHILD_NICK_NAME                                                                                                           ' + char(10)
					SET @v_dSql += '					FROM	(                                                                                                                                           ' + char(10)
					SET @v_dSql += '								SELECT	COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,PARENT_ITEM_ID,CHILD_ITEM_ID,KEY_DATE,EFF_START_DATE,EFF_END_DATE                       ' + char(10)
					SET @v_dSql += '										,PARENT_QTY,PARENT_UOM,CHILD_QTY,CHILD_UOM,PARENT_ITEM_TYPE,PARENT_ITEM_CLASS,PARENT_LEVEL_2_CODE,PARENT_LEVEL_3_NAME           ' + char(10)
					SET @v_dSql += '										,CHILD_ITEM_TYPE,CHILD_ITEM_CLASS,CHILD_LEVEL_2_CODE,CHILD_LEVEL_3_NAME                                                         ' + char(10)
					SET @v_dSql += '										,NLEVEL,NPATH,ROOT_ITEM AS ROOT                                                                                                 ' + char(10)
					SET @v_dSql += '										,ROW_NUMBER() OVER(	PARTITION BY ROOT_ITEM,COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,PARENT_ITEM_ID,CHILD_ITEM_ID,NPATH           ' + char(10)
					SET @v_dSql += '															ORDER BY COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,PARENT_ITEM_ID,CHILD_ITEM_ID,KEY_DATE DESC) AS RNUM        ' + char(10)
					SET @v_dSql += '										,PARENT_NICK_NAME,CHILD_NICK_NAME                                                                                               ' + char(10)
					SET @v_dSql += '								FROM	CTE_NODE A                                                                                                                      ' + char(10)
					SET @v_dSql += '							) A                                                                                                                                         ' + char(10)
					SET @v_dSql += '					WHERE	RNUM=1                                                                                                                                      ' + char(10)
					SET @v_dSql += '				)                                                                                                                                                       ' + char(10)
					SET @v_dSql += '	SELECT	A.*                                                                                                                                                         ' + char(10)
					SET @v_dSql += '	     , B2.ITEM_ATTRIBUTE AS CHILD_ITEM_ATTRIBUTE, B2.SETUP_ATTRIBUTE AS CHILD_SETUP_ATTRIBUTE		' + char(10)
					SET @v_dSql += '			, REPLICATE (''·'', 4 * (NLEVEL - 1)) + '' '' + A.PARENT_ITEM_ID AS PARENT_ITEM_ID2                                                                    ' + char(10)
					SET @v_dSql += '	FROM   BOM_NODE A, SCM_ITEM_M B2 WITH(NOLOCK)														' + char(10)
					SET @v_dSql += '	WHERE 1=1																							' + char(10)
					SET @v_dSql += '	AND   A.COMPANY_ID     = B2.COMPANY_ID																' + char(10)
					SET @v_dSql += '	AND   A.DIVISION_ID    = B2.DIVISION_ID																' + char(10)
					SET @v_dSql += '	AND   A.SITE_ID        = B2.SITE_ID																	' + char(10)
					SET @v_dSql += '	AND   A.CHILD_ITEM_ID  = B2.ITEM_ID																	' + char(10)
					SET @v_dSql += (SELECT  [DBO].[FN_SCM_GET_WHERE_SQL]('A.DIVISION_ID' , 'EQ', @p_division_id)) + char(10);
					SET @v_dSql += (SELECT  [DBO].[FN_SCM_GET_WHERE_SQL]('A.SITE_ID' , 'EQ', @p_site_id)) + char(10);
					SET @v_dSql += (SELECT  [DBO].[FN_SCM_GET_WHERE_SQL]('A.PLANT_ID' , 'EQ', @p_plant_id)) + char(10);
					SET @v_dSql += '	ORDER BY ROOT,A.NPATH	' + char(10)
			END

			IF @p_bom_type = 'I' AND @p_view_type = 'C'
			BEGIN
			
					SET	@v_dSql = ''
					--SET @v_dSql += '	-- Implosion / Material '+char(10);
			
				    SET @v_dSql += '	IF object_id(' +CHAR(39)+'tempdb.dbo.#SCM_BOM_M_TEMP' +CHAR(39)+') is not null DROP TABLE #SCM_BOM_M_TEMP;	' + char(10)
					SET @v_dSql += '	SELECT   A.COMPANY_ID, A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,A.PARENT_ITEM_ID,A.CHILD_ITEM_ID,A.KEY_DATE,A.EFF_START_DATE,								' + char(10)
					SET @v_dSql += '	A.EFF_END_DATE,A.PARENT_QTY,A.PARENT_UOM,A.CHILD_QTY,A.CHILD_UOM, A.ACTIVE_FLAG , A.ALT_ID , A.ALT_PRIORITY								' + char(10)
					SET @v_dSql += '	INTO #SCM_BOM_M_TEMP  FROM SCM_BOM_M A WHERE A.EFF_START_DATE <= DBO.SYSDATE1() AND A.EFF_END_DATE   >= DBO.SYSDATE1() ;			' + char(10)

					SET @v_dSql += '	IF object_id(' +CHAR(39)+'tempdb.dbo.#SCM_ITEM_M_TEMP' +CHAR(39)+') is not null DROP TABLE #SCM_ITEM_M_TEMP;	' + char(10)
					SET @v_dSql += '	SELECT COMPANY_ID, DIVISION_ID, SITE_ID,ITEM_ID, ITEM_CLASS,NICK_NAME,ACTIVE_FLAG, ITEM_TYPE INTO #SCM_ITEM_M_TEMP								' + char(10)
					SET @v_dSql += '	FROM SCM_ITEM_M WHERE ACTIVE_FLAG =' +CHAR(39)+'Y' +CHAR(39)+' ;			' + char(10)

					SET @v_dSql += '	IF object_id(' +CHAR(39)+'tempdb.dbo.#SCM_ITEM_CLASS_M_TEMP' +CHAR(39)+') is not null DROP TABLE #SCM_ITEM_CLASS_M_TEMP;	' + char(10)
					SET @v_dSql += '	SELECT LEVEL_2_CODE, LEVEL_3_NAME, CLASS_ID INTO #SCM_ITEM_CLASS_M_TEMP  FROM SCM_ITEM_CLASS_M WHERE USE_FLAG   =' +CHAR(39)+'Y' +CHAR(39)+' ;			' + char(10)		

					SET @v_dSql += '	WITH BASE_NODE	(																																																	' + char(10)			
					SET @v_dSql += '						COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,PARENT_ITEM_ID,CHILD_ITEM_ID                                                                                                                            ' + char(10)
					SET @v_dSql += '						,KEY_DATE,EFF_START_DATE,EFF_END_DATE                                                                                                                                                           ' + char(10)
					SET @v_dSql += '						,PARENT_QTY,PARENT_UOM,CHILD_QTY,CHILD_UOM,PARENT_ITEM_TYPE,PARENT_ITEM_CLASS,PARENT_LEVEL_2_CODE,PARENT_LEVEL_3_NAME                                                                           ' + char(10)
					SET @v_dSql += '						,CHILD_ITEM_TYPE,CHILD_ITEM_CLASS,CHILD_LEVEL_2_CODE,CHILD_LEVEL_3_NAME                                                                                                                         ' + char(10)
					SET @v_dSql += '						,NLEVEL,NPATH,ROOT                                                                                                                                                                              ' + char(10)
					SET @v_dSql += '					)                                                                                                                                                                                                   ' + char(10)
					SET @v_dSql += '				AS	(                                                                                                                                                                                                   ' + char(10)
					SET @v_dSql += '						SELECT	A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,A.PARENT_ITEM_ID,A.CHILD_ITEM_ID,A.KEY_DATE                                                                                             ' + char(10)
					SET @v_dSql += '								,A.EFF_START_DATE,A.EFF_END_DATE,A.PARENT_QTY,A.PARENT_UOM,A.CHILD_QTY,A.CHILD_UOM                                                                                                      ' + char(10)
					SET @v_dSql += '								,PD1.ITEM_TYPE AS PARENT_ITEM_TYPE                                                                                                                                                      ' + char(10)
					SET @v_dSql += '								,PD1.ITEM_CLASS AS PARENT_ITEM_CLASS                                                                                                                                                    ' + char(10)
					SET @v_dSql += '								,PDC1.LEVEL_2_CODE AS PARENT_LEVEL_2_CODE                                                                                                                                               ' + char(10)
					SET @v_dSql += '								,PDC1.LEVEL_3_NAME AS PARENT_LEVEL_3_NAME                                                                                                                                               ' + char(10)
					SET @v_dSql += '								,PD2.ITEM_TYPE AS CHILD_ITEM_TYPE                                                                                                                                                       ' + char(10)
					SET @v_dSql += '								,PD2.ITEM_CLASS AS CHILD_ITEM_CLASS                                                                                                                                                     ' + char(10)
					SET @v_dSql += '								,PDC2.LEVEL_2_CODE AS CHILD_LEVEL_2_CODE                                                                                                                                                ' + char(10)
					SET @v_dSql += '								,PDC2.LEVEL_3_NAME AS CHILD_LEVEL_3_NAME                                                                                                                                                ' + char(10)
					SET @v_dSql += '								,1 AS NLEVEL,CONVERT(VARCHAR(100),PARENT_ITEM_ID+''/''+CHILD_ITEM_ID) AS NPATH,PARENT_ITEM_ID AS ROOT                                                                                   ' + char(10)
					SET @v_dSql += '						FROM	#SCM_BOM_M_TEMP A(NOLOCK)                                                                                                                                                                     ' + char(10)
					SET @v_dSql += '								INNER  JOIN #SCM_ITEM_M_TEMP PD1(NOLOCK)                                                                                                                                                      ' + char(10)
					SET @v_dSql += '									ON A.COMPANY_ID=PD1.COMPANY_ID                                                                                                                                                      ' + char(10)
					SET @v_dSql += '									AND A.DIVISION_ID=PD1.DIVISION_ID                                                                                                                                                   ' + char(10)
					SET @v_dSql += '									AND A.SITE_ID=PD1.SITE_ID                                                                                                                                                           ' + char(10)
					SET @v_dSql += '									AND A.PARENT_ITEM_ID=PD1.ITEM_ID                                                                                                                                                    ' + char(10)
					SET @v_dSql += '								INNER  JOIN #SCM_ITEM_CLASS_M_TEMP PDC1(NOLOCK)                                                                                                                                               ' + char(10)
					SET @v_dSql += '									ON PD1.ITEM_CLASS=PDC1.CLASS_ID                                                                                                                                                     ' + char(10)
					SET @v_dSql += '								INNER  JOIN #SCM_ITEM_M_TEMP PD2(NOLOCK)                                                                                                                                                      ' + char(10)
					SET @v_dSql += '									ON A.COMPANY_ID=PD2.COMPANY_ID                                                                                                                                                      ' + char(10)
					SET @v_dSql += '									AND A.DIVISION_ID=PD2.DIVISION_ID                                                                                                                                                   ' + char(10)
					SET @v_dSql += '									AND A.SITE_ID=PD2.SITE_ID                                                                                                                                                           ' + char(10)
					SET @v_dSql += '									AND A.CHILD_ITEM_ID=PD2.ITEM_ID                                                                                                                                                     ' + char(10)
					SET @v_dSql += '								INNER  JOIN #SCM_ITEM_CLASS_M_TEMP PDC2(NOLOCK)                                                                                                                                               ' + char(10)
					SET @v_dSql += '									ON PD2.ITEM_CLASS=PDC2.CLASS_ID                                                                                                                                                     ' + char(10)
					SET @v_dSql += '						WHERE 1 = 1                                                                                                                                                        ' + char(10)
					--SET @v_dSql += '						WHERE A.EFF_START_DATE <= DBO.SYSDATE1()                                                                                                                                                        ' + char(10)
					--SET @v_dSql += '						AND A.EFF_END_DATE >= DBO.SYSDATE1()                                                                                                                                                            ' + char(10)
					--SET @v_dSql += '						--AND A.PARENT_ITEM_ID = ''APCCA0522B''                                                                                                                                                         ' + char(10)
					SET @v_dSql += '						AND A.CHILD_ITEM_ID = '''+ @p_item_id +'''                                                                                                                                                      ' + char(10)
					SET @v_dSql += '						AND A.ACTIVE_FLAG=''Y''                                                                                                                                                                         ' + char(10)
					--SET @v_dSql += '						AND PD1.ACTIVE_FLAG=''Y''                                                                                                                                                                       ' + char(10)
					--SET @v_dSql += '						AND PDC1.USE_FLAG=''Y''                                                                                                                                                                         ' + char(10)
					--SET @v_dSql += '						AND PD2.ACTIVE_FLAG=''Y''                                                                                                                                                                       ' + char(10)
					--SET @v_dSql += '						AND PDC2.USE_FLAG=''Y''                                                                                                                                                                         ' + char(10)
					SET @v_dSql += '						UNION ALL                                                                                                                                                                                       ' + char(10)
					SET @v_dSql += '						SELECT	A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,A.PARENT_ITEM_ID,A.CHILD_ITEM_ID,A.KEY_DATE                                                                                             ' + char(10)
					SET @v_dSql += '								,A.EFF_START_DATE,A.EFF_END_DATE,A.PARENT_QTY,A.PARENT_UOM,A.CHILD_QTY,A.CHILD_UOM                                                                                                      ' + char(10)
					SET @v_dSql += '								,PD1.ITEM_TYPE AS PARENT_ITEM_TYPE                                                                                                                                                      ' + char(10)
					SET @v_dSql += '								,PD1.ITEM_CLASS AS PARENT_ITEM_CLASS                                                                                                                                                    ' + char(10)
					SET @v_dSql += '								,PDC1.LEVEL_2_CODE AS PARENT_LEVEL_2_CODE                                                                                                                                               ' + char(10)
					SET @v_dSql += '								,PDC1.LEVEL_3_NAME AS PARENT_LEVEL_3_NAME                                                                                                                                               ' + char(10)
					SET @v_dSql += '								,PD2.ITEM_TYPE AS CHILD_ITEM_TYPE                                                                                                                                                       ' + char(10)
					SET @v_dSql += '								,PD2.ITEM_CLASS AS CHILD_ITEM_CLASS                                                                                                                                                     ' + char(10)
					SET @v_dSql += '								,PDC2.LEVEL_2_CODE AS CHILD_LEVEL_2_CODE                                                                                                                                                ' + char(10)
					SET @v_dSql += '								,PDC2.LEVEL_3_NAME AS CHILD_LEVEL_3_NAME                                                                                                                                                ' + char(10)
					SET @v_dSql += '								,NLEVEL+1 AS NLEVEL ,CONVERT(VARCHAR(100),A.PARENT_ITEM_ID+''/''+NPATH) AS NPATH,A.PARENT_ITEM_ID as ROOT                                                                               ' + char(10)
					SET @v_dSql += '						FROM	#SCM_BOM_M_TEMP A(NOLOCK)                                                                                                                                                                     ' + char(10)
					SET @v_dSql += '								INNER  JOIN BASE_NODE B                                                                                                                                                                 ' + char(10)
					--SET @v_dSql += '								--ON A.PARENT_ITEM_ID=B.CHILD_ITEM_ID                                                                                                                                                   ' + char(10)
					SET @v_dSql += '									ON A.CHILD_ITEM_ID=B.PARENT_ITEM_ID                                                                                                                                                 ' + char(10)
					SET @v_dSql += '									AND A.COMPANY_ID=B.COMPANY_ID                                                                                                                                                       ' + char(10)
					SET @v_dSql += '									AND A.DIVISION_ID=B.DIVISION_ID                                                                                                                                                     ' + char(10)
					SET @v_dSql += '									AND A.SITE_ID=B.SITE_ID                                                                                                                                                             ' + char(10)
					SET @v_dSql += '								INNER  JOIN #SCM_ITEM_M_TEMP PD1(NOLOCK)                                                                                                                                                      ' + char(10)
					SET @v_dSql += '									ON A.COMPANY_ID=PD1.COMPANY_ID                                                                                                                                                      ' + char(10)
					SET @v_dSql += '									AND A.DIVISION_ID=PD1.DIVISION_ID                                                                                                                                                   ' + char(10)
					SET @v_dSql += '									AND A.SITE_ID=PD1.SITE_ID                                                                                                                                                           ' + char(10)
					SET @v_dSql += '									AND A.PARENT_ITEM_ID=PD1.ITEM_ID                                                                                                                                                    ' + char(10)
					SET @v_dSql += '								INNER  JOIN #SCM_ITEM_CLASS_M_TEMP PDC1(NOLOCK)                                                                                                                                               ' + char(10)
					SET @v_dSql += '									ON PD1.ITEM_CLASS=PDC1.CLASS_ID                                                                                                                                                     ' + char(10)
					SET @v_dSql += '								INNER  JOIN #SCM_ITEM_M_TEMP PD2(NOLOCK)                                                                                                                                                      ' + char(10)
					SET @v_dSql += '									ON A.COMPANY_ID=PD2.COMPANY_ID                                                                                                                                                      ' + char(10)
					SET @v_dSql += '									AND A.DIVISION_ID=PD2.DIVISION_ID                                                                                                                                                   ' + char(10)
