					SET @v_dSql += '													,PARENT_ITEM_CLASS,PARENT_LEVEL_2_CODE,PARENT_LEVEL_23_CODE,NLEVEL,ROOT_ITEM,ROOT_NICK_NAME,ALT_ID,ALT_PRIORITY                                                     ' + char(10)
					--SET @v_dSql += '													--,ROW_NUMBER() OVER(PARTITION BY A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,PARENT_ITEM_ID,CHILD_ITEM_ID,NPATH                                                ' + char(10)
					--SET @v_dSql += '													--					 ORDER BY A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,PARENT_ITEM_ID,CHILD_ITEM_ID,KEY_DATE DESC) AS RNUM                                   ' + char(10)
					SET @v_dSql += '													,CASE	WHEN PARENT_LEVEL_23_CODE=''AAP'' OR PARENT_LEVEL_23_CODE=''EEP'' OR PARENT_LEVEL_23_CODE=''MMP'' THEN 1                                                    ' + char(10)
					SET @v_dSql += '															WHEN PARENT_LEVEL_2_CODE=''AMD'' OR PARENT_LEVEL_23_CODE=''AAM'' OR PARENT_LEVEL_23_CODE=''EEM'' OR PARENT_LEVEL_23_CODE=''MMT'' THEN 2                     ' + char(10)
					SET @v_dSql += '															WHEN PARENT_LEVEL_23_CODE=''AAC'' OR PARENT_LEVEL_23_CODE=''EEC'' OR PARENT_LEVEL_23_CODE=''MMC'' THEN 3                                                    ' + char(10)
					SET @v_dSql += '															WHEN PARENT_LEVEL_2_CODE=''AFC'' OR PARENT_LEVEL_2_CODE=''ASC'' OR PARENT_LEVEL_2_CODE=''AJR'' THEN 4                                                       ' + char(10)
					SET @v_dSql += '															WHEN PARENT_LEVEL_2_CODE=''ABC'' OR PARENT_LEVEL_2_CODE=''AMC'' OR PARENT_LEVEL_2_CODE=''AHC'' THEN 5                                                       ' + char(10)
					SET @v_dSql += '															WHEN PARENT_LEVEL_2_CODE=''ANR'' OR CHILD_LEVEL_2_CODE=''ANP'' THEN 6                                                                                       ' + char(10)
					SET @v_dSql += '															WHEN PARENT_LEVEL_23_CODE=''AEAAEAAP'' THEN 7                                                                                                               ' + char(10)
					SET @v_dSql += '															WHEN PARENT_LEVEL_2_CODE=''APC'' OR PARENT_LEVEL_23_CODE=''AEAAEACJ'' THEN 8                                                                                ' + char(10)
					SET @v_dSql += '															WHEN PARENT_LEVEL_2_CODE=''ASL'' THEN 9                                                                                                                     ' + char(10)
					SET @v_dSql += '															ELSE 11                                                                                                                                                     ' + char(10)
					SET @v_dSql += '													  END AS CNUM                                                                                                                                                       ' + char(10)
					SET @v_dSql += '													,B.FACTORY_ID                                                                                                                                                       ' + char(10)
					SET @v_dSql += '											FROM	ROOT A                                                                                                                                                              ' + char(10)
					SET @v_dSql += '													LEFT OUTER JOIN (	SELECT COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,FACTORY_ID,ITEM_ID                                                                               ' + char(10)
					SET @v_dSql += '																		FROM SCM_ITEM_LINE_ASSIGN_M (NOLOCK)                                                                                                            ' + char(10)
					SET @v_dSql += '																		WHERE MONTH=SUBSTRING(CONVERT(VARCHAR, dbo.SYSDATE1(), 112), 1, 6)                                                                              ' + char(10)
					SET @v_dSql += '																		AND ACTIVE_FLAG = ''Y''                                                                                                                         ' + char(10)
					SET @v_dSql += '																		GROUP BY COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,FACTORY_ID,ITEM_ID                                                                             ' + char(10)
					SET @v_dSql += '																	) B                                                                                                                                                 ' + char(10)
					SET @v_dSql += '														ON A.COMPANY_ID=B.COMPANY_ID                                                                                                                                    ' + char(10)
					SET @v_dSql += '														AND A.DIVISION_ID=B.DIVISION_ID                                                                                                                                 ' + char(10)
					SET @v_dSql += '														AND A.SITE_ID=B.SITE_ID                                                                                                                                         ' + char(10)
					SET @v_dSql += '														AND A.PLANT_ID=B.PLANT_ID                                                                                                                                       ' + char(10)
					SET @v_dSql += '														AND A.PARENT_ITEM_ID=B.ITEM_ID                                                                                                                                  ' + char(10)
					SET @v_dSql += '										) A                                                                                                                                                                             ' + char(10)
					SET @v_dSql += '								) A                                                                                                                                                                                     ' + char(10)
					SET @v_dSql += '						WHERE RNUM=1                                                                                                                                                                                    ' + char(10)
					SET @v_dSql += '					)                                                                                                                                                                                                   ' + char(10)
					SET @v_dSql += '		, BOM_DIST	(	                                                                                                                                                                                                ' + char(10)
					SET @v_dSql += '						COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,CHILD_ITEM_ID,CHILD_LEVEL_2_CODE,CHILD_LEVEL_23_CODE                                                                                                    ' + char(10)
					SET @v_dSql += '						,ALT_ID,ALT_PRIORITY,ROOT_ITEM,CNUM,RNUM,FACTORY_ID,NICK_NAME                                                                                                                                   ' + char(10)
					SET @v_dSql += '					)                                                                                                                                                                                                   ' + char(10)
					SET @v_dSql += '				AS	(                                                                                                                                                                                                   ' + char(10)
					SET @v_dSql += '						SELECT	A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,A.CHILD_ITEM_ID,A.CHILD_LEVEL_2_CODE,A.CHILD_LEVEL_23_CODE                                                                              ' + char(10)
					SET @v_dSql += '								,A.ALT_ID,A.ALT_PRIORITY,A.ROOT_ITEM,A.CNUM,A.RNUM,A.FACTORY_ID,A.NICK_NAME                                                                                                             ' + char(10)
					SET @v_dSql += '						FROM	(                                                                                                                                                                                       ' + char(10)
					SET @v_dSql += '									SELECT	A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,A.CHILD_ITEM_ID,A.CHILD_LEVEL_2_CODE,A.CHILD_LEVEL_23_CODE                                                                  ' + char(10)
					SET @v_dSql += '											,A.ALT_ID,A.ALT_PRIORITY,A.ROOT_ITEM,A.CNUM                                                                                                                                 ' + char(10)
					SET @v_dSql += '											,ROW_NUMBER() OVER(PARTITION BY A.ROOT_ITEM,A.CNUM ORDER BY ROOT_ITEM,A.FACTORY_ID,A.ALT_ID,A.ALT_PRIORITY,A.CHILD_ITEM_ID ASC) AS RNUM                                     ' + char(10)
					SET @v_dSql += '											,FACTORY_ID                                                                                                                                                                 ' + char(10)
					SET @v_dSql += '											,ROOT_NICK_NAME AS NICK_NAME                                                                                                                                                ' + char(10)
					SET @v_dSql += '									FROM	BOM_NODE A                                                                                                                                                                  ' + char(10)
					SET @v_dSql += '									WHERE 1=1                                                                                                                                                                           ' + char(10)
					SET @v_dSql += (SELECT  [DBO].[FN_SCM_GET_WHERE_SQL]('A.DIVISION_ID' , 'EQ', @p_division_id)) + char(10);
					SET @v_dSql += (SELECT  [DBO].[FN_SCM_GET_WHERE_SQL]('A.SITE_ID' , 'EQ', @p_site_id)) + char(10);
					SET @v_dSql += (SELECT  [DBO].[FN_SCM_GET_WHERE_SQL]('A.PLANT_ID' , 'EQ', @p_plant_id)) + char(10);
					SET @v_dSql += '									GROUP BY A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,A.CHILD_ITEM_ID,A.CHILD_LEVEL_2_CODE,A.CHILD_LEVEL_23_CODE		' + char(10)
					SET @v_dSql += '											,A.ALT_ID,A.ALT_PRIORITY,A.ROOT_ITEM,A.CNUM,A.FACTORY_ID,A.ROOT_NICK_NAME                                       ' + char(10)
					SET @v_dSql += '								) A                                                                                                                         ' + char(10)
					SET @v_dSql += '					)                                                                                                                                       ' + char(10)
					SET @v_dSql += '	SELECT	ROOT_ITEM AS ROOT,NICK_NAME,RNUM                                                                                                                ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=1 THEN ALT_PRIORITY END) AS bLEVEL1_A                                                                                       ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=1 THEN CHILD_ITEM_ID END) AS bLEVEL1                                                                                        ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=1 THEN FACTORY_ID END) AS bLEVEL1_P                                                                                         ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=2 THEN ALT_PRIORITY END) AS bLEVEL2_A                                                                                       ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=2 THEN CHILD_ITEM_ID END) AS bLEVEL2                                                                                        ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=2 THEN FACTORY_ID END) AS bLEVEL2_P                                                                                         ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=3 THEN ALT_PRIORITY END) AS bLEVEL3_A                                                                                       ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=3 THEN CHILD_ITEM_ID END) AS bLEVEL3                                                                                        ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=3 THEN FACTORY_ID END) AS bLEVEL3_P                                                                                         ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=4 THEN ALT_PRIORITY END) AS bLEVEL4_A                                                                                       ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=4 THEN CHILD_ITEM_ID END) AS bLEVEL4                                                                                        ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=4 THEN FACTORY_ID END) AS bLEVEL4_P                                                                                         ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=5 THEN ALT_PRIORITY END) AS bLEVEL5_A                                                                                       ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=5 THEN CHILD_ITEM_ID END) AS bLEVEL5                                                                                        ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=5 THEN FACTORY_ID END) AS bLEVEL5_P                                                                                         ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=6 THEN ALT_PRIORITY END) AS bLEVEL6_A                                                                                       ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=6 THEN CHILD_ITEM_ID END) AS bLEVEL6                                                                                        ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=6 THEN FACTORY_ID END) AS bLEVEL6_P                                                                                         ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=7 THEN ALT_PRIORITY END) AS bLEVEL7_A                                                                                       ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=7 THEN CHILD_ITEM_ID END) AS bLEVEL7                                                                                        ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=7 THEN FACTORY_ID END) AS bLEVEL7_P                                                                                         ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=8 THEN ALT_PRIORITY END) AS bLEVEL8_A                                                                                       ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=8 THEN CHILD_ITEM_ID END) AS bLEVEL8                                                                                        ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=8 THEN FACTORY_ID END) AS bLEVEL8_P                                                                                         ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=9 THEN ALT_PRIORITY END) AS bLEVEL9_A                                                                                       ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=9 THEN CHILD_ITEM_ID END) AS bLEVEL9                                                                                        ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=9 THEN FACTORY_ID END) AS bLEVEL9_P                                                                                         ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=10 THEN ALT_PRIORITY END) AS bLEVEL10_A                                                                                     ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=10 THEN CHILD_ITEM_ID END) AS bLEVEL10                                                                                      ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=10 THEN CHILD_LEVEL_2_CODE END) AS bLEVEL10_P                                                                               ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=11 THEN ALT_PRIORITY END) AS bLEVEL11_A                                                                                     ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=11 THEN CHILD_ITEM_ID END) AS bLEVEL11                                                                                      ' + char(10)
					SET @v_dSql += '			,MAX(CASE WHEN CNUM=11 THEN FACTORY_ID END) AS bLEVEL11_P                                                                                       ' + char(10)
					SET @v_dSql += '	FROM	BOM_DIST A                                                                                                                                      ' + char(10)
					SET @v_dSql += '	GROUP BY ROOT_ITEM,NICK_NAME,RNUM                                                                                                                       ' + char(10)
					SET @v_dSql += '	ORDER BY ROOT_ITEM,NICK_NAME,RNUM                                                                                                                       ' + char(10)
									

			END

			IF @p_item_id = 'ALL' AND @p_view_type = 'C'
			BEGIN
			
					SET	@v_dSql = ''
					SET @v_dSql += '	-- ALL '+char(10);
					SET @v_dSql += '	WITH ROOT AS	(                                                                                                    																						' + char(10)
					SET @v_dSql += '						SELECT	A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,A.PARENT_ITEM_ID,A.CHILD_ITEM_ID                                                                                                ' + char(10)
					SET @v_dSql += '								,PD1.ITEM_TYPE AS CHILD_ITEM_TYPE                                                                                                                                               ' + char(10)
					SET @v_dSql += '								,PD1.ITEM_CLASS AS CHILD_ITEM_CLASS                                                                                                                                             ' + char(10)
					SET @v_dSql += '								,PDC1.LEVEL_2_CODE AS CHILD_LEVEL_2_CODE                                                                                                                                        ' + char(10)
					SET @v_dSql += '								,PDC1.LEVEL_2_CODE + PDC1.LEVEL_3_CODE AS CHILD_LEVEL_23_CODE                                                                                                                   ' + char(10)
					SET @v_dSql += '								,PD.ITEM_TYPE AS PARENT_ITEM_TYPE                                                                                                                                               ' + char(10)
					SET @v_dSql += '								,PD.ITEM_CLASS AS PARENT_ITEM_CLASS                                                                                                                                             ' + char(10)
					SET @v_dSql += '								,PDC.LEVEL_2_CODE AS PARENT_LEVEL_2_CODE                                                                                                                                        ' + char(10)
					SET @v_dSql += '								,PDC.LEVEL_2_CODE + PDC.LEVEL_3_CODE AS PARENT_LEVEL_23_CODE                                                                                                                    ' + char(10)
					SET @v_dSql += '								,A.PARENT_ITEM_ID AS ROOT_ITEM                                                                                                                                                  ' + char(10)
					SET @v_dSql += '								,PD.NICK_NAME AS ROOT_NICK_NAME                                                                                                                                                 ' + char(10)
					SET @v_dSql += '								,A.ALT_ID                                                                                                                                                                       ' + char(10)
					SET @v_dSql += '								,A.ALT_PRIORITY                                                                                                                                                                 ' + char(10)
					SET @v_dSql += '								,1 AS NLEVEL                                                                                                                                                                    ' + char(10)
					SET @v_dSql += '						FROM	SCM_BOM_M A(NOLOCK)                                                                                                                                                             ' + char(10)
					SET @v_dSql += '								INNER HASH JOIN SCM_ITEM_M PD(NOLOCK)                                                                                                                                           ' + char(10)
					SET @v_dSql += '									ON A.COMPANY_ID=PD.COMPANY_ID                                                                                                                                               ' + char(10)
					SET @v_dSql += '									AND A.DIVISION_ID=PD.DIVISION_ID                                                                                                                                            ' + char(10)
					SET @v_dSql += '									AND A.SITE_ID=PD.SITE_ID                                                                                                                                                    ' + char(10)
					SET @v_dSql += '									AND A.PARENT_ITEM_ID=PD.ITEM_ID                                                                                                                                             ' + char(10)
					SET @v_dSql += '									AND PD.ACTIVE_FLAG=''Y''                                                                                                                                                    ' + char(10)
					SET @v_dSql += '									AND PD.ITEM_TYPE=''P''                                                                                                                                                      ' + char(10)
					SET @v_dSql += '								INNER HASH JOIN SCM_ITEM_CLASS_M PDC(NOLOCK)                                                                                                                                    ' + char(10)
					SET @v_dSql += '									ON PD.ITEM_CLASS=PDC.CLASS_ID                                                                                                                                               ' + char(10)
					SET @v_dSql += '									AND PDC.USE_FLAG=''Y''                                                                                                                                                      ' + char(10)
					SET @v_dSql += '								INNER HASH JOIN SCM_ITEM_M PD1(NOLOCK)                                                                                                                                          ' + char(10)
					SET @v_dSql += '									ON A.COMPANY_ID=PD1.COMPANY_ID                                                                                                                                              ' + char(10)
					SET @v_dSql += '									AND A.DIVISION_ID=PD1.DIVISION_ID                                                                                                                                           ' + char(10)
					SET @v_dSql += '									AND A.SITE_ID=PD1.SITE_ID                                                                                                                                                   ' + char(10)
					SET @v_dSql += '									AND A.CHILD_ITEM_ID=PD1.ITEM_ID                                                                                                                                             ' + char(10)
					SET @v_dSql += '									AND PD1.ACTIVE_FLAG=''Y''                                                                                                                                                   ' + char(10)
					SET @v_dSql += '									AND PD1.ITEM_TYPE <> ''R''                                                                                                                                                  ' + char(10)
					SET @v_dSql += '								INNER HASH JOIN SCM_ITEM_CLASS_M PDC1(NOLOCK)                                                                                                                                   ' + char(10)
					SET @v_dSql += '									ON PD1.ITEM_CLASS=PDC1.CLASS_ID                                                                                                                                             ' + char(10)
					SET @v_dSql += '									AND PDC1.USE_FLAG=''Y''                                                                                                                                                     ' + char(10)
					SET @v_dSql += '						--WHERE A.PARENT_ITEM_ID IN (''ACEN1021U-A1'')                                                                                                                                          ' + char(10)
					SET @v_dSql += '					)                                                                                                                                                                                           ' + char(10)
					SET @v_dSql += '		,LVL1 AS	(                                                                                                                                                                                           ' + char(10)
					SET @v_dSql += '						SELECT	A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,A.PARENT_ITEM_ID,A.CHILD_ITEM_ID                                                                                                ' + char(10)
					SET @v_dSql += '								,PD1.ITEM_TYPE AS CHILD_ITEM_TYPE                                                                                                                                               ' + char(10)
					SET @v_dSql += '								,PD1.ITEM_CLASS AS CHILD_ITEM_CLASS                                                                                                                                             ' + char(10)
					SET @v_dSql += '								,PDC1.LEVEL_2_CODE AS CHILD_LEVEL_2_CODE                                                                                                                                        ' + char(10)
					SET @v_dSql += '								,PDC1.LEVEL_2_CODE + PDC1.LEVEL_3_CODE AS CHILD_LEVEL_23_CODE                                                                                                                   ' + char(10)
					SET @v_dSql += '								,ROOT_ITEM                                                                                                                                                                      ' + char(10)
					SET @v_dSql += '								,ROOT_NICK_NAME                                                                                                                                                                 ' + char(10)
					SET @v_dSql += '								,A.ALT_ID                                                                                                                                                                       ' + char(10)
					SET @v_dSql += '								,A.ALT_PRIORITY                                                                                                                                                                 ' + char(10)
					SET @v_dSql += '								,2 AS NLEVEL                                                                                                                                                                    ' + char(10)
					SET @v_dSql += '						FROM	SCM_BOM_M A(NOLOCK)                                                                                                                                                             ' + char(10)
					SET @v_dSql += '								INNER HASH JOIN ROOT B                                                                                                                                                          ' + char(10)
					SET @v_dSql += '									ON A.PARENT_ITEM_ID=B.CHILD_ITEM_ID                                                                                                                                         ' + char(10)
					SET @v_dSql += '								INNER HASH JOIN SCM_ITEM_M PD1(NOLOCK)                                                                                                                                          ' + char(10)
					SET @v_dSql += '									ON A.COMPANY_ID=PD1.COMPANY_ID                                                                                                                                              ' + char(10)
					SET @v_dSql += '									AND A.DIVISION_ID=PD1.DIVISION_ID                                                                                                                                           ' + char(10)
					SET @v_dSql += '									AND A.SITE_ID=PD1.SITE_ID                                                                                                                                                   ' + char(10)
					SET @v_dSql += '									AND A.CHILD_ITEM_ID=PD1.ITEM_ID                                                                                                                                             ' + char(10)
					SET @v_dSql += '									AND PD1.ACTIVE_FLAG=''Y''                                                                                                                                                   ' + char(10)
					--SET @v_dSql += '									--AND PD1.ITEM_TYPE <> ''R''                                                                                                                                                ' + char(10)
					SET @v_dSql += '								INNER HASH JOIN SCM_ITEM_CLASS_M PDC1(NOLOCK)                                                                                                                                   ' + char(10)
					SET @v_dSql += '									ON PD1.ITEM_CLASS=PDC1.CLASS_ID                                                                                                                                             ' + char(10)
					SET @v_dSql += '									AND PDC1.USE_FLAG=''Y''                                                                                                                                                     ' + char(10)
					SET @v_dSql += '						WHERE A.EFF_START_DATE <= DBO.SYSDATE1()                                                                                                                                                ' + char(10)
					SET @v_dSql += '						AND A.EFF_END_DATE >= DBO.SYSDATE1()                                                                                                                                                    ' + char(10)
					SET @v_dSql += '						AND (PD1.ITEM_TYPE <> ''R'' OR (PD1.ITEM_TYPE = ''R'' AND PDC1.LEVEL_2_CODE=''APC''))                                                                                                   ' + char(10)
					SET @v_dSql += '					)                                                                                                                                                                                           ' + char(10)
					SET @v_dSql += '		,LVL2 AS	(                                                                                                                                                                                           ' + char(10)
					SET @v_dSql += '						SELECT	A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,A.PARENT_ITEM_ID,A.CHILD_ITEM_ID                                                                                                ' + char(10)
					SET @v_dSql += '								,PD1.ITEM_TYPE AS CHILD_ITEM_TYPE                                                                                                                                               ' + char(10)
					SET @v_dSql += '								,PD1.ITEM_CLASS AS CHILD_ITEM_CLASS                                                                                                                                             ' + char(10)
					SET @v_dSql += '								,PDC1.LEVEL_2_CODE AS CHILD_LEVEL_2_CODE                                                                                                                                        ' + char(10)
					SET @v_dSql += '								,PDC1.LEVEL_2_CODE + PDC1.LEVEL_3_CODE AS CHILD_LEVEL_23_CODE                                                                                                                   ' + char(10)
					SET @v_dSql += '								,ROOT_ITEM                                                                                                                                                                      ' + char(10)
					SET @v_dSql += '								,ROOT_NICK_NAME                                                                                                                                                                 ' + char(10)
					SET @v_dSql += '								,A.ALT_ID                                                                                                                                                                       ' + char(10)
					SET @v_dSql += '								,A.ALT_PRIORITY                                                                                                                                                                 ' + char(10)
					SET @v_dSql += '								,3 AS NLEVEL                                                                                                                                                                    ' + char(10)
					SET @v_dSql += '						FROM	SCM_BOM_M A(NOLOCK)                                                                                                                                                             ' + char(10)
					SET @v_dSql += '								INNER HASH JOIN LVL1 B                                                                                                                                                          ' + char(10)
					SET @v_dSql += '									ON A.PARENT_ITEM_ID=B.CHILD_ITEM_ID                                                                                                                                         ' + char(10)
					SET @v_dSql += '								INNER HASH JOIN SCM_ITEM_M PD1(NOLOCK)                                                                                                                                          ' + char(10)
					SET @v_dSql += '									ON A.COMPANY_ID=PD1.COMPANY_ID                                                                                                                                              ' + char(10)
					SET @v_dSql += '									AND A.DIVISION_ID=PD1.DIVISION_ID                                                                                                                                           ' + char(10)
					SET @v_dSql += '									AND A.SITE_ID=PD1.SITE_ID                                                                                                                                                   ' + char(10)
					SET @v_dSql += '									AND A.CHILD_ITEM_ID=PD1.ITEM_ID                                                                                                                                             ' + char(10)
					SET @v_dSql += '									AND PD1.ACTIVE_FLAG=''Y''                                                                                                                                                   ' + char(10)
					--SET @v_dSql += '									--AND PD1.ITEM_TYPE <> ''R''                                                                                                                                                ' + char(10)
