					SET @v_dSql += '	, BOM_NODE AS	(                                                                                                                                                                                           ' + char(10)
					SET @v_dSql += '						SELECT	COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,PARENT_ITEM_ID,CHILD_ITEM_ID,CHILD_ITEM_TYPE,CHILD_ITEM_CLASS                                                                           ' + char(10)
					SET @v_dSql += '								,CHILD_LEVEL_2_CODE,CHILD_LEVEL_23_CODE,NLEVEL,ROOT_ITEM,ROOT_NICK_NAME,ALT_ID,ALT_PRIORITY,CNUM,FACTORY_ID                                                                     ' + char(10)
					SET @v_dSql += '						FROM	(                                                                                                                                                                               ' + char(10)
					SET @v_dSql += '									SELECT	COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,PARENT_ITEM_ID,CHILD_ITEM_ID,CHILD_ITEM_TYPE                                                                                ' + char(10)
					SET @v_dSql += '											,CHILD_ITEM_CLASS,CHILD_LEVEL_2_CODE,CHILD_LEVEL_23_CODE,NLEVEL,ROOT_ITEM,ROOT_NICK_NAME,ALT_ID,ALT_PRIORITY                                                        ' + char(10)
					SET @v_dSql += '											,ROW_NUMBER() OVER(	PARTITION BY ROOT_ITEM,PARENT_ITEM_ID,CHILD_ITEM_ID,FACTORY_ID                                                                                  ' + char(10)
					SET @v_dSql += '																ORDER BY PARENT_ITEM_ID,CHILD_ITEM_ID,FACTORY_ID) AS RNUM                                                                                       ' + char(10)
					SET @v_dSql += '											,CNUM,FACTORY_ID                                                                                                                                                    ' + char(10)
					SET @v_dSql += '									FROM	(                                                                                                                                                                   ' + char(10)
					SET @v_dSql += '												SELECT	A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,PARENT_ITEM_ID                                                                                          ' + char(10)
					SET @v_dSql += '														,CHILD_ITEM_ID,CHILD_ITEM_TYPE,CHILD_ITEM_CLASS,CHILD_LEVEL_2_CODE,CHILD_LEVEL_23_CODE                                                                  ' + char(10)
					SET @v_dSql += '														,NLEVEL,ROOT_ITEM,ROOT_NICK_NAME,ALT_ID,ALT_PRIORITY                                                                                                    ' + char(10)
					SET @v_dSql += '														--,ROW_NUMBER() OVER(	PARTITION BY A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,PARENT_ITEM_ID,CHILD_ITEM_ID,NPATH                                 ' + char(10)
					SET @v_dSql += '														--						ORDER BY A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,PARENT_ITEM_ID,CHILD_ITEM_ID,KEY_DATE DESC) AS RNUM                    ' + char(10)
					SET @v_dSql += '														,CASE	WHEN CHILD_LEVEL_23_CODE=''AAP'' OR CHILD_LEVEL_23_CODE=''EEP'' OR CHILD_LEVEL_23_CODE=''MMP'' THEN 1                                           ' + char(10)
					SET @v_dSql += '																WHEN CHILD_LEVEL_2_CODE=''AMD'' OR CHILD_LEVEL_23_CODE=''AAM'' OR CHILD_LEVEL_23_CODE=''EEM'' OR CHILD_LEVEL_23_CODE=''MMT'' THEN 2             ' + char(10)
					SET @v_dSql += '																WHEN CHILD_LEVEL_23_CODE=''AAC'' OR CHILD_LEVEL_23_CODE=''EEC'' OR CHILD_LEVEL_23_CODE=''MMC'' THEN 3                                           ' + char(10)
					SET @v_dSql += '																WHEN CHILD_LEVEL_2_CODE=''AFC'' OR CHILD_LEVEL_2_CODE=''ASC'' OR CHILD_LEVEL_2_CODE=''AJR'' THEN 4                                              ' + char(10)
					SET @v_dSql += '																WHEN CHILD_LEVEL_2_CODE=''ABC'' OR CHILD_LEVEL_2_CODE=''AMC'' OR CHILD_LEVEL_2_CODE=''AHC'' THEN 5                                              ' + char(10)
					SET @v_dSql += '																WHEN CHILD_LEVEL_2_CODE=''ANR'' OR CHILD_LEVEL_2_CODE=''ANP'' THEN 6                                                                            ' + char(10)
					SET @v_dSql += '																WHEN CHILD_LEVEL_23_CODE=''AEAAEAAP'' THEN 7                                                                                                    ' + char(10)
					SET @v_dSql += '																WHEN CHILD_LEVEL_2_CODE=''APC'' OR CHILD_LEVEL_23_CODE=''AEAAEACJ'' THEN 8                                                                      ' + char(10)
