					SET @v_dSql += '																			GROUP BY COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,FACTORY_ID,ITEM_ID                                                                 ' + char(10)
					SET @v_dSql += '																		) B                                                                                                                                     ' + char(10)
					SET @v_dSql += '															ON A.COMPANY_ID=B.COMPANY_ID                                                                                                                        ' + char(10)
					SET @v_dSql += '															AND A.DIVISION_ID=B.DIVISION_ID                                                                                                                     ' + char(10)
					SET @v_dSql += '															AND A.SITE_ID=B.SITE_ID                                                                                                                             ' + char(10)
					SET @v_dSql += '															AND A.PLANT_ID=B.PLANT_ID                                                                                                                           ' + char(10)
					SET @v_dSql += '															AND A.CHILD_ITEM_ID=B.ITEM_ID                                                                                                                       ' + char(10)
					SET @v_dSql += '												UNION ALL                                                                                                                                                       ' + char(10)
					SET @v_dSql += '												SELECT	A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID                                                                                                         ' + char(10)
					SET @v_dSql += '														,PARENT_ITEM_ID,PARENT_ITEM_ID,PARENT_ITEM_TYPE,PARENT_ITEM_CLASS,PARENT_LEVEL_2_CODE,PARENT_LEVEL_23_CODE                                              ' + char(10)
					SET @v_dSql += '														,NLEVEL,ROOT_ITEM,ROOT_NICK_NAME,ALT_ID,ALT_PRIORITY                                                                                                    ' + char(10)
					SET @v_dSql += '														--,ROW_NUMBER() OVER(	PARTITION BY A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,PARENT_ITEM_ID,CHILD_ITEM_ID,NPATH                                 ' + char(10)
					SET @v_dSql += '														--						ORDER BY A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,PARENT_ITEM_ID,CHILD_ITEM_ID,KEY_DATE DESC) AS RNUM                    ' + char(10)
					SET @v_dSql += '														,CASE	WHEN PARENT_LEVEL_23_CODE=''AAP'' OR PARENT_LEVEL_23_CODE=''EEP'' OR PARENT_LEVEL_23_CODE=''MMP'' THEN 1                                        ' + char(10)
					SET @v_dSql += '																WHEN PARENT_LEVEL_2_CODE=''AMD'' OR PARENT_LEVEL_23_CODE=''AAM'' OR PARENT_LEVEL_23_CODE=''EEM'' OR PARENT_LEVEL_23_CODE=''MMT'' THEN 2         ' + char(10)
					SET @v_dSql += '																WHEN PARENT_LEVEL_23_CODE=''AAC'' OR PARENT_LEVEL_23_CODE=''EEC'' OR PARENT_LEVEL_23_CODE=''MMC'' THEN 3                                        ' + char(10)
					SET @v_dSql += '																WHEN PARENT_LEVEL_2_CODE=''AFC'' OR PARENT_LEVEL_2_CODE=''ASC'' OR PARENT_LEVEL_2_CODE=''AJR'' THEN 4                                           ' + char(10)
					SET @v_dSql += '																WHEN PARENT_LEVEL_2_CODE=''ABC'' OR PARENT_LEVEL_2_CODE=''AMC'' OR PARENT_LEVEL_2_CODE=''AHC'' THEN 5                                           ' + char(10)
					SET @v_dSql += '																WHEN PARENT_LEVEL_2_CODE=''ANR'' OR CHILD_LEVEL_2_CODE=''ANP'' THEN 6                                                                           ' + char(10)
					SET @v_dSql += '																WHEN PARENT_LEVEL_23_CODE=''AEAAEAAP'' THEN 7                                                                                                   ' + char(10)
					SET @v_dSql += '																WHEN PARENT_LEVEL_2_CODE=''APC'' OR PARENT_LEVEL_23_CODE=''AEAAEACJ'' THEN 8                                                                    ' + char(10)
					SET @v_dSql += '																WHEN PARENT_LEVEL_2_CODE=''ASL'' THEN 9                                                                                                         ' + char(10)
					SET @v_dSql += '																ELSE 11                                                                                                                                         ' + char(10)
					SET @v_dSql += '														 END AS CNUM                                                                                                                                            ' + char(10)
					SET @v_dSql += '														,B.FACTORY_ID                                                                                                                                           ' + char(10)
					SET @v_dSql += '												FROM	ROOT A                                                                                                                                                  ' + char(10)
					SET @v_dSql += '														LEFT OUTER JOIN (	SELECT	COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,FACTORY_ID,ITEM_ID                                                                  ' + char(10)
					SET @v_dSql += '																			FROM	SCM_ITEM_LINE_ASSIGN_M (NOLOCK)                                                                                             ' + char(10)
					SET @v_dSql += '																			WHERE MONTH=SUBSTRING(CONVERT(VARCHAR, dbo.SYSDATE1(), 112), 1, 6)                                                                  ' + char(10)
