					SET @v_dSql += '															AND A.PARENT_ITEM_ID=B.ITEM_ID                                                                                                                      ' + char(10)
					SET @v_dSql += '											) A                                                                                                                                                                 ' + char(10)
					SET @v_dSql += '								) A                                                                                                                                                                             ' + char(10)
					SET @v_dSql += '						WHERE RNUM=1                                                                                                                                                                            ' + char(10)
					SET @v_dSql += '					)                                                                                                                                                                                           ' + char(10)
					SET @v_dSql += '		, BOM_DIST	(                                                                                                                                                                                           ' + char(10)
					SET @v_dSql += '						COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,CHILD_ITEM_ID,CHILD_LEVEL_2_CODE,CHILD_LEVEL_23_CODE,ALT_ID                                                                                     ' + char(10)
					SET @v_dSql += '						,ALT_PRIORITY,ROOT_ITEM,CNUM,RNUM,FACTORY_ID,NICK_NAME                                                                                                                                  ' + char(10)
					SET @v_dSql += '					)                                                                                                                                                                                           ' + char(10)
					SET @v_dSql += '				AS	(                                                                                                                                                                                           ' + char(10)
					SET @v_dSql += '						SELECT	A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,A.CHILD_ITEM_ID,A.CHILD_LEVEL_2_CODE,A.CHILD_LEVEL_23_CODE                                                                      ' + char(10)
					SET @v_dSql += '								,A.ALT_ID,A.ALT_PRIORITY,A.ROOT_ITEM,A.CNUM,A.RNUM,A.FACTORY_ID,A.NICK_NAME                                                                                                     ' + char(10)
					SET @v_dSql += '						FROM	(                                                                                                                                                                               ' + char(10)
					SET @v_dSql += '									SELECT	A.COMPANY_ID,A.DIVISION_ID,A.SITE_ID,A.PLANT_ID,A.CHILD_ITEM_ID,A.CHILD_LEVEL_2_CODE,A.CHILD_LEVEL_23_CODE                                                          ' + char(10)
					SET @v_dSql += '											,A.ALT_ID,A.ALT_PRIORITY,A.ROOT_ITEM,A.CNUM                                                                                                                         ' + char(10)
					SET @v_dSql += '											,ROW_NUMBER() OVER(	PARTITION BY ROOT_ITEM,A.CNUM                                                                                                                   ' + char(10)
					SET @v_dSql += '																ORDER BY ROOT_ITEM,A.FACTORY_ID,A.ALT_ID,A.ALT_PRIORITY,A.CHILD_ITEM_ID ASC) AS RNUM                                                            ' + char(10)
					SET @v_dSql += '											,A.FACTORY_ID                                                                                                                                                       ' + char(10)
					SET @v_dSql += '											,ROOT_NICK_NAME AS NICK_NAME                                                                                                                                        ' + char(10)
					SET @v_dSql += '									FROM	BOM_NODE A                                                                                                                                                          ' + char(10)
					SET @v_dSql += '									WHERE	1=1                                                                                                                                                                 ' + char(10)
					SET @v_dSql += (SELECT  [DBO].[FN_SCM_GET_WHERE_SQL]('A.DIVISION_ID' , 'EQ', @p_division_id)) + char(10);
