					SET @v_dsql += '									GROUP BY COMPANY_ID,DIVISION_ID,SITE_ID,PLANT_ID,CHILD_ITEM_ID,CHILD_LEVEL_2_CODE,CHILD_LEVEL_23_CODE,ALT_ID   		' + char(10)
					SET @v_dsql += '											,ALT_PRIORITY,ROOT_ITEM,CNUM,FACTORY_ID,ROOT_NICK_NAME                                                      ' + char(10)
