					SET @v_dsql += '			,MAX(CASE WHEN CNUM=4 THEN FACTORY_ID END) AS bLEVEL4_P                                                                                     ' + char(10)
					SET @v_dsql += '			,MAX(CASE WHEN CNUM=5 THEN ALT_PRIORITY END) AS bLEVEL5_A                                                                                   ' + char(10)
					SET @v_dsql += '			,MAX(CASE WHEN CNUM=5 THEN CHILD_ITEM_ID END) AS bLEVEL5                                                                                    ' + char(10)
					SET @v_dsql += '			,MAX(CASE WHEN CNUM=5 THEN FACTORY_ID END) AS bLEVEL5_P                                                                                     ' + char(10)
