					SET @v_dsql += '			,MAX(CASE WHEN CNUM=10 THEN CHILD_ITEM_ID END) AS bLEVEL10                                                                                  ' + char(10)
					SET @v_dsql += '			,MAX(CASE WHEN CNUM=10 THEN CHILD_LEVEL_2_CODE END) AS bLEVEL10_P                                                                           ' + char(10)
